import {
  collides,
  step,
  resolveBrickHit,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// --- Issue #1: the ball must bounce off bricks, not plow through ----------

// A small helper: one brick, default-ish points, alive.
function brick(x, y) {
  return { x, y, w: 72, h: 20, row: 0, alive: true, points: 10 };
}

test('resolveBrickHit: bottom face hit flips vy, leaves vx, pushes out', () => {
  // Ball climbing (vy < 0) into the brick's bottom face.
  const ball = { x: 110, y: 117, r: 7, vx: 50, vy: -200 };
  resolveBrickHit(ball, brick(100, 100));
  assert.equal(ball.vy, 200, 'vy flips on a top/bottom hit');
  assert.equal(ball.vx, 50, 'the other component is left exactly as it was');
  assert.equal(ball.y, 127, 'ball pushed out below the brick (y = 120 + 7)');
});

test('resolveBrickHit: side face hit flips vx, leaves vy, pushes out', () => {
  // Ball moving right into the brick's left face.
  const ball = { x: 95, y: 110, r: 7, vx: 200, vy: 30 };
  resolveBrickHit(ball, brick(100, 100));
  assert.equal(ball.vx, -200, 'vx flips on a side hit');
  assert.equal(ball.vy, 30, 'the other component is left exactly as it was');
  assert.equal(ball.x, 93, 'ball pushed out left of the brick (x = 100 - 7)');
});

test('resolveBrickHit: corner hit (equal penetration) flips both components', () => {
  // Diagonal overlap: penetration is equal on both axes.
  const ball = { x: 94, y: 94, r: 7, vx: 200, vy: -200 };
  resolveBrickHit(ball, brick(100, 100));
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, 200);
  assert.equal(ball.x, 93, 'pushed out up-left of the brick');
  assert.equal(ball.y, 93);
});

test('step: top face hit bounces the ball up and pushes it out', () => {
  const state = createState(1);
  state.ball = { x: 110, y: 90, r: 7, vx: 0, vy: 300 };
  state.bricks = [brick(100, 100)];
  step(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false);
  assert.ok(state.ball.vy < 0, 'bounced up off the top face');
  assert.ok(state.ball.y <= 93, 'ball repositioned above the brick');
});

test('step: side face hit bounces the ball horizontally', () => {
  const state = createState(1);
  state.ball = { x: 92, y: 110, r: 7, vx: 300, vy: 0 };
  state.bricks = [brick(100, 100)];
  step(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false);
  assert.ok(state.ball.vx < 0, 'bounced left off the side face');
  assert.equal(state.ball.vy, 0, 'vertical component untouched');
  assert.ok(state.ball.x <= 93, 'ball repositioned left of the brick');
});

test('step: push-out prevents the sticky bounce (no re-flip next frame)', () => {
  const state = createState(1);
  state.ball = { x: 110, y: 187, r: 7, vx: 0, vy: -600 };
  state.bricks = [brick(100, 160)];
  step(state, 1 / 60); // hits the brick's bottom face
  assert.equal(state.bricks[0].alive, false);
  assert.ok(state.ball.vy > 0, 'bounced down');
  assert.ok(state.ball.y >= 180, 'ball pushed out below the brick');
  step(state, 1 / 60); // next frame: must NOT collide again and re-flip
  assert.ok(state.ball.vy > 0, 'no re-flip: velocity keeps pointing down');
});

test('step: seam between two bricks destroys both and bounces exactly once', () => {
  // The gap is 8 px and the ball is 14 px across: straddling the seam the
  // ball overlaps BOTH bricks in the same pass. Applying the bounce to each
  // brick would flip vx twice and cancel out.
  const state = createState(1);
  state.ball = { x: 176, y: 210, r: 7, vx: 100, vy: 0 };
  state.bricks = [brick(100, 200), brick(180, 200)];
  step(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.bricks[1].alive, false);
  assert.equal(state.ball.vx, -100, 'flipped exactly once (a double flip cancels out)');
});

test('step: fast ball does not tunnel through a brick (level-6 speed)', () => {
  // ballSpeed(6) = 710 px/s and a stuttered frame is capped at 50 ms:
  // 35.5 px per step, against the 34 px (BRICK_H + 2*r) it takes to cross a
  // brick. A single discrete check would jump right over it.
  const state = createState(6);
  state.ball = { x: 136, y: 91.5, r: 7, vx: 0, vy: 710 };
  state.bricks = [brick(100, 100)];
  step(state, 0.05);
  assert.equal(state.bricks[0].alive, false, 'brick hit despite the high speed');
  assert.ok(state.ball.vy < 0, 'ball bounced off the brick top face');
});

