export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

// Maximum distance (px) travelled in a single integration substep. The ball
// crosses a brick in BRICK_H + 2 * BALL_R = 34 px, so a discrete position
// check can jump over one at level 6 (35.5 px per capped frame — see #1
// "tunnelling"). Sub-dividing every step keeps a sampled position inside the
// brick's span. 12 px also stays under 2 * BALL_R, so even a corner clip is
// always caught.
const MAX_SUBSTEP_PX = 12;

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face resolution lives in resolveBrickHit(), applied
// by step()'s per-substep brick pass.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves a single ball/brick overlap (see #1):
//   - per face: the axis with the SMALLER penetration is the face that was
//     hit — flip vy on a top/bottom hit, vx on a side hit, and leave the
//     other component exactly as it was;
//   - corner: equal penetrations mean a diagonal hit — flip both components;
//   - push out: the ball is repositioned just outside the brick along the hit
//     axis(es), to the nearest face. Without this it still overlaps on the
//     next frame and the bounce re-triggers forever (sticky bounce).
// Mutates `ball` in place; returns nothing.
export function resolveBrickHit(ball, brick) {
  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  // Penetration depth per face, used to pick the nearest outside position.
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);

  if (overlapX < overlapY) {
    // Side hit: the horizontal penetration is the shallowest.
    ball.vx = -ball.vx;
    if (left < right) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    // Top/bottom hit: the vertical penetration is the shallowest.
    ball.vy = -ball.vy;
    if (top < bottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  } else {
    // Corner: equal penetration on both axes — diagonal hit, flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    if (left < right) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
    if (top < bottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  }
}

// Brick pass for ONE substep: every brick the ball overlaps is destroyed, but
// the bounce is applied EXACTLY ONCE. The grid gap is 8 px and the ball is
// 14 px across, so a ball in a seam overlaps two bricks in the same pass;
// resolving against each of them would flip the velocity twice and cancel out
// (see #1 "neighbours"). Scoring order (combo then score) is preserved from
// the original frame() loop.
function brickCollisions(state) {
  const { ball, bricks } = state;
  let hit = null;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (hit === null) hit = brick;
  }
  if (hit !== null) resolveBrickHit(ball, hit);
}

